mapper.select:
/*	businessTrip.selectBusinessTripCount */
SELECT
	count(TRIP_IDX) as cnt
FROM
	lab_business_trip
WHERE 1 = 1
	
		 
		AND DOC_OWNER = #{userId} 
		
	    
	    AND DOC_OWNER IN (
	    	SELECT USER_ID from lab_team_manager_view ltmv
			WHERE ltmv.TEAM_MANAGER_ID = #{userId}
	    ) 
	    
	    
	    
	    
	    
		 AND DOC_OWNER = #{userId}

/* businessTrip.selectBusinessTripList */ SELECT tmp.* , CASE WHEN tmp.TRIP_TYPE = 'I' THEN '국내' WHEN tmp.TRIP_TYPE = 'O' THEN '해외' END AS TRIP_TYPE_TXT , FN_GET_USER_NAME(tmp.DOC_OWNER) as DOC_OWNER_NAME , FN_GET_USER_NAME(tmp.DOC_OWNER) as USER_NAME , FN_GET_CODE_NAME('DOC_STATUS', tmp.STATUS) AS STATUS_TXT FROM ( SELECT row_number() over (order by TRIP_IDX DESC) as rnum , TRIP_IDX , TRIP_TYPE , TITLE , TRIP_START_DATE , TRIP_END_DATE
, TRIP_CONTENTS , TRIP_COST , OVER_REASON , TRIP_EFFECT , REG_USER , DOC_OWNER , STATUS , IS_LAST , IS_DELETE , VERSION_NO FROM lab_business_trip WHERE 1 = 1
AND DOC_OWNER = #{userId}
AND DOC_OWNER IN ( SELECT USER_ID from lab_team_manager_view ltmv WHERE ltmv.TEAM_MANAGER_ID = #{userId} )
AND DOC_OWNER = #{userId}
AND IS_DELETE = 'N' AND IS_LAST = 'Y'
)tmp WHERE rnum between #{startRow} and #{endRow}

mapper.insert:
/*	businessTrip.insertBusinessTrip */
INSERT INTO lab_business_trip(
	TRIP_IDX
	
	, PLAN_IDX
	
	, TRIP_TYPE
	, TITLE
	, TRIP_START_DATE
	, TRIP_END_DATE
	
	, TRIP_CONTENTS
	, TRIP_COST
	, OVER_REASON
	, TRIP_EFFECT
	, REG_USER
	, DOC_OWNER
	, STATUS
	, IS_LAST
	, IS_DELETE
	, VERSION_NO	
)VALUES(
	#{idx}
	
	, #{planIdx}
	
	, #{tripType}
	, #{title}
	, #{tripStartDate}
	, #{tripEndDate}
	
	, #{tripContents}
	, #{tripCost}
	, #{overReason}
	, #{tripEffect}
	, #{userId}
	, #{userId}
	, #{status}
	, 'Y'
	, 'N'
	, 1		
)

mapper.update:
/*	businessTrip.updateBusinessTrip */
UPDATE 
	lab_business_trip
SET 
	
	TRIP_TYPE = #{tripType}
	
	, PLAN_IDX = #{planIdx}
	
	, TITLE = #{title}
	, TRIP_START_DATE = #{tripStartDate}
	, TRIP_END_DATE = #{tripEndDate}
	
	, TRIP_CONTENTS = #{tripContents}
	, TRIP_COST = #{tripCost}
	, OVER_REASON = #{overReason}
	, TRIP_EFFECT = #{tripEffect}
	
	, STATUS = #{status}
	
WHERE 1 = 1
	AND TRIP_IDX = #{idx}

mapper.delete:
